import React, { useEffect, useState, useRef } from 'react';
import './app.css';
import './components/autosuggest.css'; // Import the CSS file
import CardComponent from './components/CardComponent';
import Autosuggest from 'react-autosuggest';

const OpenWeather_Api_Key = "3b79f0d5ac9962fba1bdfc40537607fa";

function App() {
  const [weatherData, setWeatherData] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [fadeIn, setFadeIn] = useState(true);
  const inputRef = useRef(null);

  useEffect(() => {
    fetchWeatherData('San Diego'); // Default city
  }, []);

  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.style.fontSize = '16px'; // Set font size to at least 16px to prevent zoom on focus
    }
  }, []);

  const fetchWeatherData = async (city) => {
    try {
      const weatherResponse = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${OpenWeather_Api_Key}&units=imperial`);
      if (!weatherResponse.ok) {
        throw new Error('Network response was not ok');
      }
      const weatherData = await weatherResponse.json();

      const { lat, lon } = weatherData.coord;
      const reverseGeocodingResponse = await fetch(`https://api.openweathermap.org/geo/1.0/reverse?lat=${lat}&lon=${lon}&limit=1&appid=${OpenWeather_Api_Key}`);
      if (!reverseGeocodingResponse.ok) {
        throw new Error('Network response was not ok');
      }
      const reverseGeocodingData = await reverseGeocodingResponse.json();
      const state = reverseGeocodingData[0].state;

      setWeatherData({
        city_name: `${weatherData.name}, ${state}`,
        weather: weatherData.weather[0].main,
        temperature: weatherData.main.temp,
        humidity: weatherData.main.humidity,
        wind_speed: weatherData.wind.speed
      });
      setFadeIn(true); // Trigger fade-in effect after data is fetched
    } catch (error) {
      console.error('Error fetching weather data:', error);
    }
  };

  const fetchSuggestions = ({ value }) => {
    if (value.length > 2) {
      fetch(`http://api.openweathermap.org/data/2.5/find?q=${value}&type=like&sort=population&cnt=5&appid=${OpenWeather_Api_Key}`)
        .then(response => response.json())
        .then(data => {
          setSuggestions(data.list.map(item => ({
            id: item.id,
            name: `${item.name}, ${item.sys.country}`
          })));
        })
        .catch(error => console.error('Error fetching location suggestions:', error));
    } else {
      setSuggestions([]);
    }
  };

  const clearSuggestions = () => {
    setSuggestions([]);
  };

  const getSuggestionValue = (suggestion) => suggestion.name;

  const renderSuggestion = (suggestion) => (
    <div>
      {suggestion.name}
    </div>
  );

  const handleChange = (event, { newValue }) => {
    setSearchTerm(newValue);
  };

  const handleSuggestionSelected = (event, { suggestion }) => {
    setSearchTerm(suggestion.name);
    setFadeIn(false); // Trigger fade-out effect
    setTimeout(() => {
      fetchWeatherData(suggestion.name); // Fetch weather data for the selected location
      clearSuggestions();
      setFadeIn(true); // Trigger fade-in effect after data is fetched
    }, 1000); // Delay fetch by 1 second to allow fade-out effect
  };

  const handleKeyPress = (event) => {
    if (event.key === 'Enter') {
      event.preventDefault(); // Prevent default form submission behavior
      setFadeIn(false); // Trigger fade-out effect
      setTimeout(() => {
        fetchWeatherData(searchTerm); // Fetch weather data for the entered location
        clearSuggestions();
        setFadeIn(true); // Trigger fade-in effect after data is fetched
      }, 1000); // Delay fetch by 1 second to allow fade-out effect
    }
  };

  const getTemperatureCaption = (temperature) => {
    if (temperature < 50) {
      return 'It\'s quitec cold today<br /> make sure to bundle up!';
    } else if (temperature < 70) {
      return 'It\'s a bit chilly outside <br />a light jacket should do.';
    } else if (temperature < 80) {
      return 'The weather is pleasantly warm today <br />enjoy!';
    } else if (temperature < 90) {
      return 'It\'s getting hot out there<br />stay cool and hydrated!';
    } else {
      return 'It\'s extremely hot today<br /> take precautions to stay safe!';
    }
  }

  const getHumidityCaption = (humidity) => {
    if (humidity < 30) {
      return 'The air is quite dry today<br /> stay hydrated!';
    } else if (humidity < 60) {
      return 'The air is comfortably humid today<br /> enjoy!';
    } else {
      return 'The air is very humid today<br /> stay cool and dry!';
    }
  }

  const getWindSpeedCaption = (wind_speed) => {
    if (wind_speed < 10) {
      return 'There is a light breeze today<br /> enjoy!';
    } else if (wind_speed < 20) {
      return 'It\'s a bit windy today<br /> hold onto your hat!';
    } else {
      return 'It\'s very windy today<br /> be careful out there!';
    }
  }

  const getWeatherConditionCaption = (weather) => {
    if (weather === 'Clear') {
      return 'The sky is clear today<br /> enjoy the sunshine!';
    } else if (weather === 'Clouds') {
      return 'It\'s cloudy today<br /> a perfect day for a walk!';
    } else if (weather === 'Rain') {
      return 'It\'s raining today<br /> don\'t forget your umbrella!';
    } else if (weather === 'Snow') {
      return 'It\'s snowing today<br /> bundle up and stay warm!';
    } else {
      return 'The weather is unpredictable today<br /> be prepared for anything!';
    }
  }

  return (
    <div className={`app ${fadeIn ? 'fade-in' : 'fade-out'}`}>
      <header>
        <h1>{weatherData ? weatherData.city_name : 'City Name'}</h1>
      </header>

      <div className="body">
        {weatherData ? (
          <div className='weather-cards'>
            <CardComponent 
              title="Weather Condition" 
              value={weatherData.weather} 
              caption={getWeatherConditionCaption(weatherData.weather)} 
            />
            <CardComponent 
              title="Temperature" 
              value={weatherData.temperature} 
              unit="°F" 
              caption={getTemperatureCaption(weatherData.temperature)} 
            />
            <CardComponent 
              title="Humidity" 
              value={weatherData.humidity} 
              unit="%" 
              caption={getHumidityCaption(weatherData.humidity)} 
            />
            <CardComponent 
              title="Wind Speed" 
              value={weatherData.wind_speed} 
              unit="mph" 
              caption={getWindSpeedCaption(weatherData.wind_speed)} 
            />
          </div>
        ) : (
          <p>Loading...</p>
        )}
      </div>

      <footer>
        <Autosuggest
          suggestions={suggestions}
          onSuggestionsFetchRequested={fetchSuggestions}
          onSuggestionsClearRequested={clearSuggestions}
          getSuggestionValue={getSuggestionValue}
          renderSuggestion={renderSuggestion}
          inputProps={{
            placeholder: 'Enter City Name',
            value: searchTerm,
            onChange: handleChange,
            onKeyPress: handleKeyPress, // Handle key press event
            ref: inputRef, // Attach ref to input field
          }}
          highlightFirstSuggestion={true}
          onSuggestionSelected={handleSuggestionSelected}
          theme={{
            container: 'autosuggest__container',
            input: 'autosuggest__input',
            inputFocused: 'autosuggest__input--focused',
            suggestionsContainer: 'autosuggest__suggestions-container',
            suggestionsContainerOpen: 'autosuggest__suggestions-container--open',
            suggestionsList: 'autosuggest__suggestions-list',
            suggestion: 'autosuggest__suggestion',
            suggestionHighlighted: 'autosuggest__suggestion--highlighted',
          }}
        />
      </footer>
    </div>
  );
}

export default App;
